"use strict";

// Shim for `import { Agent, fetch } from "undici"` used by the vendored
// sparkDash bench modules. Node's global fetch IS undici internally, but it
// validates the `dispatcher` option against its own bundled Dispatcher, so a
// foreign Agent instance would be rejected. We therefore strip `dispatcher`
// (and other undici-only init keys) and delegate to globalThis.fetch.

class Agent {
  constructor(opts) {
    this.opts = opts || {};
  }
  async close() {}
  async destroy() {}
}

function stripInit(init) {
  if (!init || typeof init !== "object") return init;
  const out = Object.assign({}, init);
  delete out.dispatcher;
  return out;
}

function fetch(input, init) {
  return globalThis.fetch(input, stripInit(init));
}

module.exports = { Agent, fetch };
module.exports.default = module.exports;